    ["文本文本文本文本<DarkHighlight>文本文本</>文本文本文本文本文本文本文本文本"] = "Текст текст текст текст<DarkHighlight> текст текст</> текст текст текст текст текст текст текст",
    ["是否重启水泵，还原所有水管位置？"] = "Хотите перезапустить водяной насос и восстановить положение всех водопроводных труб?",
